    require(amount <= account.cents) { "saldo insuficiente" }
    return account.copy(cents = account.cents - amount)
}

fun main() {
    val before = Account("a", 100)
    check(debit(before, 30) == Account("a", 70))
    check(before.cents == 100L)
    check(debit(before, 100).cents == 0L)
    val error = runCatching { debit(before, 101) }.exceptionOrNull()
    check(error is IllegalArgumentException)
}

