  | { ok: false; error: string };

function parseCents(value: unknown): ParseResult {
  if (typeof value !== 'string' || !/^[0-9]{1,15}$/.test(value)) {
    return { ok: false, error: 'use de 1 a 15 dígitos' };
  }
  return { ok: true, cents: BigInt(value) };
}

function describe(result: ParseResult): string {
  if (!result.ok) return result.error;
  return `${result.cents} centavos`;
}

