import { useState } from 'react';
import type { FormEvent } from 'react';

export default function App() {
  const [name, setName] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const trimmed = name.trim();
  const error = submitted && trimmed.length === 0 ? 'Informe um nome' : '';

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitted(true);
  }

  return <form onSubmit={submit}>
    <label htmlFor="name">Nome</label>
    <input id="name" value={name}
      onChange={event => { setName(event.target.value); setSubmitted(false); }}
      aria-invalid={Boolean(error)} aria-describedby="name-feedback" />
    <button type="submit">Validar</button>
    <p id="name-feedback" role="status">
      {error || (submitted ? `Olá, ${trimmed}` : '')}
    </p>
  </form>;
}

