package example;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
public class DoubleController {
    @GetMapping("/double/{value}")
    public Map<String, Long> doubleValue(@PathVariable("value") long value) {
        if (value < 0 || value > Long.MAX_VALUE / 2) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "valor fora do limite");
        }
        return Map.of("result", value * 2);
    }
}

