suspend fun fetchPart(value: Int): Int {
    require(value >= 0) { "valor inválido" }
    delay(10)
    return value
}

suspend fun combined(): Int = withTimeout(2_000) {
    coroutineScope {
        val first = async { fetchPart(2) }
        val second = async { fetchPart(3) }
        first.await() + second.await()
    }
}

fun main() = runBlocking {
    check(combined() == 5)
    try {
        fetchPart(-1)
        error("deveria rejeitar")
    } catch (expected: IllegalArgumentException) {
