import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.serialization.StringDeserializer;

public class Main {
    public static void main(String[] args) {
        Properties config = new Properties();
        config.put("bootstrap.servers", "localhost:9092");
        config.put("group.id", "study-syntax");
        config.put("enable.auto.commit", "false");
        config.put("auto.offset.reset", "earliest");
        config.put("key.deserializer", StringDeserializer.class.getName());
        config.put("value.deserializer", StringDeserializer.class.getName());
        try (KafkaConsumer<String, String> client = new KafkaConsumer<>(config)) {
            client.subscribe(List.of("study-events"));
            for (int i = 0; i < 5; i++) {
                var records = client.poll(Duration.ofSeconds(1));
                for (var record : records) System.out.println(record.value());
                if (!records.isEmpty()) client.commitSync();
            }
        }
    }
}

